from .api.exceptions import ManagedObjectNotFound, SoapApiError


class ManagedObject:

    def __init__(self, api, configuration, meta_class, meta_version, mo_id, operation, **parameters):
        """
        :param CmDataRepositoryWebServiceAPI api:
        :param configuration.Actual|configuration.Plan|configuration.Reference configuration:
        :param string mo_id: e.g. PLMN-PLMN/MRBTS-12345
        :param string meta_class: e.g. 'com.nokia.mrbts:MRBTS' (can be obtained using get_managed_objects)
        :param string meta_version: e.g. 'MRBTS17A_1701_003' (can be obtained using get_managed_objects)
        :param string operation: CREATE or DELETE or UPDATE (corresponds to 'Change to Modify')
        :param \\** parameters: new parameters e.g. autoConfMode='true', btsName='my BTS', ...
        """
        self.api = api
        self.configuration = configuration
        self.meta_class = meta_class
        self.meta_version = meta_version
        self.mo_id = mo_id
        self.operation = operation
        self.parameters = parameters

    @classmethod
    def get(cls, api, configuration, mo_id):
        """
        Get managed object from CM Editor.

        :param CmDataRepositoryWebServiceAPI api:
        :param configuration.Actual|configuration.Plan|configuration.Reference configuration:
        :param string mo_id: e.g. PLMN-PLMN/MRBTS-12345
        :rtype: ManagedObject
        """
        try:
            mo = api.get_managed_objects(configuration.conf_id, mo_id)
        except SoapApiError as e:
            if 'ERR_OBJECT_NOT_FOUND' in str(e).upper():
                exc_msg = f'Managed object {mo_id} does not exist in configuration {configuration}'
                raise ManagedObjectNotFound(exc_msg)
            else:
                raise e
        parameters = cls._create_parameters(mo)
        return ManagedObject(api, configuration, mo['metaClass'], mo['metaVersion'],
                             mo['moId'], mo['operation'], **parameters)

    @classmethod
    def _create_parameters(cls, mo):
        """
        Create MO parameters dictionary from the raw format (returned by zeep library).

        :param mo: can be obtained using get_managed_objects e.g.

        Example output
        **************
        ::

            {
                'btsName': 'my BTS',
                'autoConfMode': 'false'
            }

        :param mo: can be obtained using get_managed_objects e.g.

            Example MO
            **********
            ::

                {
                    'metaClass': 'com.nokia.mrbts:MRBTS',
                    'metaVersion': 'MRBTS17A_1701_003',
                    'moId': 'PLMN-PLMN/MRBTS-222222',
                    'operation': 'UPDATE',
                    '_value_1': [
                        {
                            'p': {
                                '_value_1': 'false',
                                'name': 'autoConfMode'
                            }
                        }
                    ]
                }

        :return: mo parameters e.g. {'autoConfMode': 'false'}
        :rtype: dict(string, (string|list(string)|list(dict(string, string)))
        """
        parameters = {}
        for element in mo['_value_1']:
            if 'structList' in element:
                parameters.update(cls._convert_from_struct_list(element['structList']))
            elif 'scalarList' in element:
                parameters.update(cls._convert_from_scalar_list(element['scalarList']))
            else:
                parameters.update({element['p']['name']: element['p']['_value_1']})
        return parameters

    @staticmethod
    def _convert_from_struct_list(struct_list):
        """
        :param struct_list:

        Example structList
        *******************
        ::

            {
                'structList': {
                    'item': [
                        {
                            'p': [
                                {
                                    '_value_1': '0',
                                    'name': 'blacklistTopo'
                                },
                                {
                                    '_value_1': '65535',
                                    'name': 'freqEutra'
                                }
                            ]
                        },
                        {
                            'p': [
                                {
                                    '_value_1': '1',
                                    'name': 'blacklistTopo'
                                },
                                {
                                    '_value_1': '65535',
                                    'name': 'freqEutra'
                                }
                            ]
                        }
                    ],
                    'name': 'blacklistHoL'
                }
            }

        :return: e.g. {'blacklistHoL': [{'blacklistTopo': '0', 'freqEutra': '65535'},
            {'blacklistTopo': '1', 'freqEutra': '65535'}]}
        :rtype: dict(string, list(dict(string, string)))
        """
        return {struct_list['name']: [{p['name']: p['_value_1'] for p in item['p']} for item in struct_list['item']]}

    @staticmethod
    def _convert_from_scalar_list(scalar_list):
        """
        :param scalar_list:

        Example scalarList
        *******************
        ::

            {
                'scalarList': {
                    'p': [
                        {
                            '_value_1': '2.2.2.2',
                            'name': None
                        },
                        {
                            '_value_1': '1.1.1.1',
                            'name': None
                        }
                    ],
                    'name': 'ntpServerIpAddrList'
                }
            }

        :return: e.g. {'ntpServerIpAddrList': ['2.2.2.2', '1.1.1.1']}
        :rtype: dict(string, list(string))
        """
        return {scalar_list['name']: [p['_value_1'] for p in scalar_list['p']]}

    def create(self):
        """
        Create managed object in CM Editor.
        """
        managed_object = self.api.prepare_managed_object(
            self.meta_class, self.meta_version, self.mo_id, self.operation, self.parameters)
        self.api.create_managed_objects(self.configuration.conf_id, managed_object)

    def edit(self, operation=None, **parameters):
        """
        Edit managed object parameters in CM Editor.

        :param string operation: CREATE or DELETE or UPDATE (corresponds to 'Change to Modify')
        :param \\** parameters: new parameters e.g. autoConfMode='true', btsName='my BTS', ...
        """
        self.operation = operation or self.operation
        self.parameters.update(parameters)
        managed_object = self.api.prepare_managed_object(
            self.meta_class, self.meta_version, self.mo_id, self.operation, self.parameters)
        self.api.update_managed_objects(self.configuration.conf_id, managed_object)

    def delete(self):
        """
        Delete managed object from CM Editor.
        """
        self.api.delete_managed_objects(self.configuration.conf_id, self.mo_id)

    def __repr__(self):
        return f'{self.mo_id} (configuration: {self.configuration})'
